@js:

var items=[];
var wide={layout_flexGrow:1,layout_flexBasisPercent:1};
var cell={layout_flexGrow:1,layout_flexBasisPercent:0.25};
function add(title,url,style){items.push({title:String(title),url:url,style:style||cell});}
function onePageUrl(hostKind,path,params,setup){
  return "@js:\n"+
    "\n"+
    (setup||"")+
    "var out=null;if(Number(page||1)===1)out="+(hostKind==="feed"?"lrtsFeedUrl":"lrtsUrl")+"(java,source,"+JSON.stringify(path)+","+JSON.stringify(params||{})+");out;";
}
function feedPageUrl(path,params){
  return "@js:\n"+
    "\n"+
    "var p=Number(page||1),refer=p===1?'':String(source.get('lrts_feed_refer')||'end');\n"+
    "if(p===1)source.put('lrts_feed_refer','');\n"+
    "var args="+JSON.stringify(params||{})+";if(p>1&&"+JSON.stringify(path)+"==='/lrts/cgi/homepage/homePageFeedList'){args.showRankModule='0';args.size='20';}args.referId=refer;var out=null;if(refer!=='end')out=lrtsFeedUrl(java,source,"+JSON.stringify(path)+",args);out;";
}
function categoryUrl(entityId){
  return "@js:\n"+
    "\n"+
    "var eid="+JSON.stringify(entityId)+";\n"+
    "var out=null;\n"+
    "if(page==1){source.put('lrts_book_ids','');out=lrtsUrl(java,source,'/yyting/label/filterResources.action',{dsize:'20',entityId:eid,entityType:'3',pageNum:'1',showFilters:'1'});}else{var ids=String(source.get('lrts_book_ids')||'').split(',').filter(function(x){return x;});var start=(page-1)*20;var part=ids.slice(start,start+20);if(part.length){out=lrtsUrl(java,source,'/yyting/label/filterResources.action',{bookIds:'['+part.join(',')+']',dsize:'20',entityId:'0',entityType:'0',pageNum:'0',showFilters:'0'});}}\n"+
    "out;";
}
add("推荐",feedPageUrl("/lrts/cgi/homepage/homePageFeedList",{recommendedSwitch:"0",showRankModule:"1",size:"26"}),cell);
add("小说",onePageUrl("api","/yyting/page/novelChannelPage",{channelId:"50000152",channelShowStyle:"5",preferenceType:"",recommendedSwitch:"0",respType:"0"}),cell);
add("会员",onePageUrl("feed","/lrts/cgi/homepage/vipPage",{}),cell);
add("儿童",feedPageUrl("/lrts/cgi/homepage/childrenChannelPageFeedList",{category:"0",channelId:"5337203",recommendedSwitch:"0",size:"20"}),cell);
add("音乐",onePageUrl("api","/yyting/musicradio/channelPage",{hv:"1.434.0"},"source.put('lrts_music_tab','');\n"),cell);
add("榜单",onePageUrl("api","/yyting/ranking/resList.action",{filterType:"0",pageNum:"1",pageSize:"100",rangeType:"6",rankId:"14680"}),cell);

add("儿童分类",null,wide);
try{
  var childBody=JSON.parse(String(java.ajax(lrtsFeedUrl(java,source,"/lrts/cgi/homepage/childrenChannelMenuList",{channelId:"5337203"}))));
  (childBody.data&&childBody.data.categoryList||[]).forEach(function(category){
    add(category.categoryName,feedPageUrl("/lrts/cgi/homepage/childrenChannelPageFeedList",{category:String(category.category),channelId:"5337203",recommendedSwitch:"0",size:"20"}),cell);
  });
}catch(e){java.log("懒人听书儿童分类加载失败: "+e);}

add("音乐频道",null,wide);
try{
  var musicBody=JSON.parse(String(java.ajax(lrtsUrl(java,source,"/yyting/musicradio/channelPage",{hv:"1.434.0"}))));
  (musicBody.data&&musicBody.data.tabList||[]).forEach(function(tab){
    add(tab.name,onePageUrl("api","/yyting/musicradio/recMusicService/fetchMusicList",{id:String(tab.id),referId:"",pageSize:"20"}),cell);
  });
}catch(e){java.log("懒人听书音乐频道加载失败: "+e);}

add("榜单",null,wide);
try{
  var rankBody=JSON.parse(String(java.ajax(lrtsUrl(java,source,"/yyting/ranking/rankingsGroupList.action",{groupId:"0",groupType:"1",recommendedSwitch:"8"}))));
  (rankBody.data&&rankBody.data.list||[]).forEach(function(group){
    var groupName=group.rankingsGroupInfoView&&group.rankingsGroupInfoView.name||"榜单";
    add(groupName,null,wide);
    (group.rankingsList||[]).forEach(function(rank){
      var rankType=Number(rank.rankType||0);
      var rankUrl;
      if(rankType===10){
        rankUrl="@js:\n"+
          "\n"+
          "var p=Number(page||1);lrtsUrl(java,source,'/yyting/music/rankingsItemList.action',{filterType:"+JSON.stringify(String(rank.filterType))+",pageNum:String(p),pageSize:'100',rangeType:"+JSON.stringify(String(rank.rangeType))+",rankId:"+JSON.stringify(String(rank.rankId))+"});";
      }else if(rankType===2){
        rankUrl=null;
      }else{
        rankUrl="@js:\n"+
          "\n"+
          "var p=Number(page||1);lrtsUrl(java,source,'/yyting/ranking/resList.action',{filterType:"+JSON.stringify(String(rank.filterType))+",pageNum:String(p),pageSize:'100',rangeType:"+JSON.stringify(String(rank.rangeType))+",rankId:"+JSON.stringify(String(rank.rankId))+"});";
      }
      if(rankUrl)add(rank.rankName,rankUrl,cell);
    });
  });
}catch(e){java.log("懒人听书榜单加载失败: "+e);}

[{id:"9011",title:"分类标签 · 男频"},{id:"9012",title:"分类标签 · 女频"}].forEach(function(group){
  add(group.title,null,wide);
  try{
    var body=JSON.parse(String(java.ajax(lrtsUrl(java,source,"/yyting/label/labelList.action",{id:group.id,showLocation:"2"}))));
    (body.data&&body.data.list||[]).forEach(function(label,index){
      add(label.name,categoryUrl(group.id+"_"+label.id),cell);
    });
  }catch(e){java.log("懒人听书分类标签加载失败: "+e);}
});
JSON.stringify(items);

