var LR_BASE="https://gzapi.mting.info";
var LR_FEED_BASE=LR_BASE.replace(".mting.info",".lanrentingshu.com");
var LR_APP_BASE="https://shapi.mting.info";
var LR_SALT="vYCmm+6CFVykQk5w0wiUDliCQRA=";
var LR_SESSION_KEYS=["token","imei","nwt","mode","lrid","ostar36","userMode","duId"];
function lrtsResolveSession(source,java) {
  var raw=String(source.get("lrts_session")||"").trim();
  if(!raw){
    throw new Error("本书源不含内置账号，请先在书源登录中填写本人抓包的 8 项会话参数");
  }
  var custom;
  try{
    custom=JSON.parse(raw);
  }catch(parseError){
    throw new Error("个人抓包会话格式无效，请在书源登录中重新填写并保存");
  }
  var candidate={};
  var missing=[];
  LR_SESSION_KEYS.forEach(function(key){
    var value=custom[key];
    if(value===null||value===undefined||String(value).trim()==="")missing.push(key);
    else candidate[key]=String(value).trim();
  });
  if(missing.length){
    throw new Error("个人抓包会话缺少参数："+missing.join("、")+"，请在书源登录中补全");
  }
  return candidate;
}
function lrtsSignedUrl(java, source, base, path, params) {
  params=params||{};
  var LR_SESSION=lrtsResolveSession(source,java);
  Object.keys(LR_SESSION).forEach(function(key){
    if(LR_SESSION[key]!==null&&LR_SESSION[key]!==undefined&&LR_SESSION[key]!=="") params[key]=String(LR_SESSION[key]);
  });
  var q=parseInt(String(source.get("lrts_q")||"0"),10);
  if(!isFinite(q)||q<0) q=0;
  q=q+1;
  source.put("lrts_q",String(q));
  params.q=String(q);
  params.ts=String(Date.now());
  var keys=Object.keys(params).filter(function(key){return params[key]!==null&&params[key]!==undefined;}).sort();
  var canonical=path+"?"+keys.map(function(key){return key+"="+String(params[key]);}).join("&");
  params.sc=String(java.md5Encode(canonical+LR_SALT));
  return base+path+"?"+Object.keys(params).filter(function(key){return params[key]!==null&&params[key]!==undefined;}).map(function(key){return encodeURIComponent(key)+"="+encodeURIComponent(String(params[key]));}).join("&");
}
function lrtsUrl(java, source, path, params) { return lrtsSignedUrl(java,source,LR_BASE,path,params); }
function lrtsFeedUrl(java, source, path, params) { return lrtsSignedUrl(java,source,LR_FEED_BASE,path,params); }
function lrtsAppUrl(java, source, path, params) { return lrtsSignedUrl(java,source,LR_APP_BASE,path,params); }
// QMC eKey decryption for Legado's Rhino runtime.
// Decrypted bytes are returned through the audio player's JSON-array data source.
function lrtsU8(value) {
  return Number(value) & 255;
}

function lrtsSetByte(bytes, index, value) {
  value = Number(value) & 255;
  bytes[index] = value > 127 ? value - 256 : value;
}

function lrtsReadU32BE(bytes, offset) {
  return (((lrtsU8(bytes[offset]) << 24) |
    (lrtsU8(bytes[offset + 1]) << 16) |
    (lrtsU8(bytes[offset + 2]) << 8) |
    lrtsU8(bytes[offset + 3])) >>> 0);
}

function lrtsWriteU32BE(output, offset, value) {
  output[offset] = (value >>> 24) & 255;
  output[offset + 1] = (value >>> 16) & 255;
  output[offset + 2] = (value >>> 8) & 255;
  output[offset + 3] = value & 255;
}

function lrtsTeaDecryptBlock(input, key) {
  var left = lrtsReadU32BE(input, 0);
  var right = lrtsReadU32BE(input, 4);
  var words = [
    lrtsReadU32BE(key, 0),
    lrtsReadU32BE(key, 4),
    lrtsReadU32BE(key, 8),
    lrtsReadU32BE(key, 12)
  ];
  var sum = 0xe3779b90;
  for (var round = 0; round < 16; round++) {
    var rightMix = ((((left << 4) + words[2]) ^
      (left + sum) ^ ((left >>> 5) + words[3])) >>> 0);
    right = (right - rightMix) >>> 0;
    var leftMix = ((((right << 4) + words[0]) ^
      (right + sum) ^ ((right >>> 5) + words[1])) >>> 0);
    left = (left - leftMix) >>> 0;
    sum = (sum - 0x9e3779b9) >>> 0;
  }
  var output = new Array(8);
  lrtsWriteU32BE(output, 0, left);
  lrtsWriteU32BE(output, 4, right);
  return output;
}

function lrtsSliceBytes(bytes, start, end) {
  var output = [];
  var limit = Math.min(Number(end), bytes.length);
  for (var index = Number(start); index < limit; index++) output.push(lrtsU8(bytes[index]));
  return output;
}

function lrtsXorBlock(left, right) {
  var output = new Array(8);
  for (var index = 0; index < 8; index++) output[index] = lrtsU8(left[index]) ^ lrtsU8(right[index]);
  return output;
}

function lrtsTencentTeaDecrypt(input, key) {
  if (input.length < 16 || input.length % 8 !== 0) throw new Error("QMC TEA data length is invalid");
  var decrypted = lrtsTeaDecryptBlock(lrtsSliceBytes(input, 0, 8), key);
  var padding = decrypted[0] & 7;
  var outputLength = input.length - 1 - padding - 2 - 7;
  if (outputLength < 0) throw new Error("QMC TEA padding is invalid");
  var output = new Array(outputLength);
  var previousCipher = [0, 0, 0, 0, 0, 0, 0, 0];
  var currentCipher = lrtsSliceBytes(input, 0, 8);
  var inputOffset = 8;
  var blockOffset = 1 + padding;

  function nextBlock() {
    previousCipher = currentCipher;
    currentCipher = lrtsSliceBytes(input, inputOffset, inputOffset + 8);
    decrypted = lrtsTeaDecryptBlock(lrtsXorBlock(decrypted, currentCipher), key);
    inputOffset += 8;
    blockOffset = 0;
  }

  for (var skipped = 0; skipped < 2;) {
    if (blockOffset < 8) {
      blockOffset++;
      skipped++;
    } else {
      nextBlock();
    }
  }
  for (var outputOffset = 0; outputOffset < outputLength;) {
    if (blockOffset < 8) {
      output[outputOffset++] = decrypted[blockOffset] ^ previousCipher[blockOffset];
      blockOffset++;
    } else {
      nextBlock();
    }
  }
  for (var zeroIndex = 0; zeroIndex < 7; zeroIndex++) {
    if (decrypted[blockOffset] !== previousCipher[blockOffset]) {
      throw new Error("QMC TEA zero check failed");
    }
    blockOffset++;
  }
  return output;
}

function lrtsAsciiBytes(text) {
  var output = new Array(String(text).length);
  for (var index = 0; index < output.length; index++) output[index] = String(text).charCodeAt(index) & 255;
  return output;
}

function lrtsBase64Bytes(java, text) {
  var javaBytes = java.base64DecodeToByteArray(String(text));
  var output = new Array(javaBytes.length);
  for (var index = 0; index < javaBytes.length; index++) output[index] = lrtsU8(javaBytes[index]);
  return output;
}

function lrtsBytesToAscii(bytes) {
  var output = "";
  for (var index = 0; index < bytes.length; index += 256) {
    var part = bytes.slice(index, Math.min(index + 256, bytes.length));
    output += String.fromCharCode.apply(String, part);
  }
  return output;
}

function lrtsStartsWithBytes(bytes, prefix) {
  if (bytes.length < prefix.length) return false;
  for (var index = 0; index < prefix.length; index++) {
    if (lrtsU8(bytes[index]) !== lrtsU8(prefix[index])) return false;
  }
  return true;
}

function lrtsSimpleKey(salt, length) {
  var output = new Array(length);
  for (var index = 0; index < length; index++) {
    output[index] = Math.floor(Math.abs(Math.tan(salt + index * 0.1)) * 100) & 255;
  }
  return output;
}

function lrtsDeriveQmcKey(java, eKey) {
  var raw = lrtsBase64Bytes(java,eKey);
  var v2Prefix = lrtsAsciiBytes("QQMusic EncV2,Key:");
  if (lrtsStartsWithBytes(raw, v2Prefix)) {
    raw = raw.slice(v2Prefix.length);
    raw = lrtsTencentTeaDecrypt(raw, lrtsAsciiBytes("386ZJY!@#*$%^&)("));
    raw = lrtsTencentTeaDecrypt(raw, lrtsAsciiBytes("**#!(#$%&^a1cZ,T"));
    raw = lrtsBase64Bytes(java,lrtsBytesToAscii(raw));
  }
  if (raw.length < 16) throw new Error("QMC eKey is too short");
  var simpleKey = lrtsSimpleKey(106, 8);
  var teaKey = new Array(16);
  for (var index = 0; index < 8; index++) {
    teaKey[index * 2] = simpleKey[index];
    teaKey[index * 2 + 1] = raw[index];
  }
  return raw.slice(0, 8).concat(lrtsTencentTeaDecrypt(raw.slice(8), teaKey));
}

function lrtsImulU32(left, right) {
  var low = left & 65535;
  var high = (left >>> 16) & 65535;
  return ((low * right + (((high * right) & 65535) << 16)) >>> 0);
}

function lrtsQmcDecrypt(java, bytes, eKey) {
  var key = lrtsDeriveQmcKey(java,eKey);
  if (key.length <= 300) {
    for (var mapIndex = 0; mapIndex < bytes.length; mapIndex++) {
      var mapOffset = mapIndex > 0x7fff ? mapIndex % 0x7fff : mapIndex;
      var keyIndex = (mapOffset * mapOffset + 71214) % key.length;
      var rotate = ((keyIndex & 7) + 4) % 8;
      var value = key[keyIndex];
      var mapMask = ((value << rotate) | (value >>> rotate)) & 255;
      lrtsSetByte(bytes, mapIndex, lrtsU8(bytes[mapIndex]) ^ mapMask);
    }
    return key.length;
  }

  var size = key.length;
  var box = new Array(size);
  var cursor = 0;
  var index;
  for (index = 0; index < size; index++) box[index] = index & 255;
  for (index = 0; index < size; index++) {
    cursor = (cursor + box[index] + key[index % size]) % size;
    var swap = box[index];
    box[index] = box[cursor];
    box[cursor] = swap;
  }
  var hash = 1;
  for (index = 0; index < key.length; index++) {
    if (key[index] === 0) continue;
    var nextHash = lrtsImulU32(hash, key[index]);
    if (nextHash === 0 || nextHash <= hash) break;
    hash = nextHash;
  }

  function segmentSkip(id) {
    var seed = key[id % size];
    if (!seed) throw new Error("QMC RC4 seed is zero");
    return Math.floor((hash / ((id + 1) * seed)) * 100) % size;
  }

  function firstSegment(position, length, offset) {
    for (var firstIndex = 0; firstIndex < length; firstIndex++) {
      lrtsSetByte(bytes, position + firstIndex,
        lrtsU8(bytes[position + firstIndex]) ^ key[segmentSkip(offset + firstIndex)]);
    }
  }

  function segment(position, length, offset) {
    var segmentBox = box.slice(0);
    var left = 0;
    var right = 0;
    var skip = (offset % 5120) + segmentSkip(Math.floor(offset / 5120));
    for (var segmentIndex = -skip; segmentIndex < length; segmentIndex++) {
      left = (left + 1) % size;
      right = (segmentBox[left] + right) % size;
      var segmentSwap = segmentBox[left];
      segmentBox[left] = segmentBox[right];
      segmentBox[right] = segmentSwap;
      if (segmentIndex >= 0) {
        var mask = segmentBox[(segmentBox[left] + segmentBox[right]) % size];
        lrtsSetByte(bytes, position + segmentIndex,
          lrtsU8(bytes[position + segmentIndex]) ^ mask);
      }
    }
  }

  var offset = 0;
  var processed = 0;
  var remaining = bytes.length;
  function advance(length) {
    offset += length;
    processed += length;
    remaining -= length;
  }
  if (offset < 128) {
    var firstLength = Math.min(remaining, 128 - offset);
    firstSegment(0, firstLength, offset);
    advance(firstLength);
  }
  if (remaining && offset % 5120 !== 0) {
    var partialLength = Math.min(remaining, 5120 - (offset % 5120));
    segment(processed, partialLength, offset);
    advance(partialLength);
  }
  while (remaining > 5120) {
    segment(processed, 5120, offset);
    advance(5120);
  }
  if (remaining) segment(processed, remaining, offset);
  return key.length;
}

function lrtsAudioFormat(bytes) {
  var head = "";
  for (var index = 0; index < Math.min(4, bytes.length); index++) head += String.fromCharCode(lrtsU8(bytes[index]));
  if (head === "OggS") return { mime: "audio/ogg", ext: "ogg" };
  if (head === "fLaC") return { mime: "audio/flac", ext: "flac" };
  if (head.substring(0, 3) === "ID3" || (bytes.length > 1 && lrtsU8(bytes[0]) === 255 && (lrtsU8(bytes[1]) & 224) === 224)) {
    return { mime: "audio/mpeg", ext: "mp3" };
  }
  throw new Error("QMC decrypted data has an unsupported header");
}

function lrtsAudioDataSource(bytes, format) {
  var encoded = String(Packages.android.util.Base64.encodeToString(bytes, 2) || "");
  if (!encoded) throw new Error("QMC audio Base64 encoding failed");
  return JSON.stringify(["data:" + format.mime + ";base64," + encoded]);
}

function lrtsLoadAllCatalog(java, source, marker) {
  var bookId=String(marker.bookId||"");
  var entityType=String(marker.entityType||"1");
  var total=parseInt(String(marker.sections||"0"),10);
  var pageSize=1000;
  var pageCount=isFinite(total)&&total>0?Math.ceil(total/pageSize):100;
  var all=[];
  if(!bookId)throw new Error("目录标记缺少 bookId");
  for(var pageNum=1;pageNum<=pageCount;pageNum++){
    var body=null;
    var lastError=null;
    for(var attempt=0;attempt<2;attempt++){
      try{
        var pageUrl=lrtsAppUrl(java,source,"/yyting/bookclient/ClientGetBookResource.action",{
          bookId:bookId,
          isUp:"0",
          pageNum:String(pageNum),
          pageSize:String(pageSize),
          sceneId:"B3",
          sortType:"0"
        });
        body=JSON.parse(String(java.ajax(pageUrl)||"{}"));
        if(!body||!Array.isArray(body.list))throw new Error(String(body&&body.msg||"目录响应缺少 list"));
        lastError=null;
        break;
      }catch(error){lastError=error;}
    }
    if(lastError)throw new Error("第"+pageNum+"页目录获取失败: "+lastError);
    var list=body.list||[];
    if(!list.length)break;
    for(var index=0;index<list.length;index++){
      var item=list[index];
      item._lrtsBookId=bookId;
      item._lrtsEntityType=entityType;
      all.push(item);
    }
    if(list.length<pageSize)break;
  }
  if(isFinite(total)&&total>0&&all.length<total){
    throw new Error("目录不完整: "+all.length+"/"+total);
  }
  if(isFinite(total)&&total>0&&all.length>total)all=all.slice(0,total);
  return all;
}

