source.loginUrl:
var LR_LOGIN_FIELDS=[
  {name:"token",key:"token"},
  {name:"imei",key:"imei"},
  {name:"nwt",key:"nwt"},
  {name:"mode",key:"mode"},
  {name:"lrid",key:"lrid"},
  {name:"ostar36",key:"ostar36"},
  {name:"userMode",key:"userMode"},
  {name:"duId",key:"duId"}
];

function lrtsLoginField(name){
  try{
    if(result&&typeof result.get==="function")return String(result.get(name)||"").trim();
  }catch(e1){}
  try{
    if(result&&result[name]!==null&&result[name]!==undefined)return String(result[name]).trim();
  }catch(e2){}
  return "";
}

function login(){
  var session={};
  var missing=[];
  LR_LOGIN_FIELDS.forEach(function(field){
    var value=lrtsLoginField(field.name);
    if(!value)missing.push(field.name);
    session[field.key]=value;
  });
  if(missing.length){
    java.longToast("请完整填写以下参数：\n"+missing.join("、"));
    return;
  }
  source.put("lrts_session",JSON.stringify(session));
  source.put("lrts_q","0");
  try{
    var map=new Packages.java.util.HashMap();
    LR_LOGIN_FIELDS.forEach(function(field){map.put(field.name,session[field.key]);});
    java.upLoginData(map);
  }catch(saveError){}
  java.longToast("个人 App 会话已保存并启用");
}

function lrtsCaptureTip(){
  java.longToast("本书源不提供内置账号，仅支持使用你本人的抓包会话。\n请从懒人听书 Android 客户端 8.8.03 的 HAR 请求参数中提取并填写 token、imei、lrid、duId、ostar36、userMode、nwt、mode。\n其他版本的字段或签名可能不同，不能保证兼容；请勿填写其他 App 的参数。");
}

function lrtsSessionStatus(){
  try{
    var saved=JSON.parse(String(source.get("lrts_session")||"{}"));
    var complete=LR_LOGIN_FIELDS.every(function(field){
      return saved[field.key]!==null&&saved[field.key]!==undefined&&String(saved[field.key]).trim()!=="";
    });
    java.longToast(complete?"个人抓包会话已配置":"尚未配置个人抓包会话，当前无法使用");
  }catch(error){
    java.longToast("个人抓包会话数据无效，请清除后重新填写");
  }
}

function lrtsClearSession(){
  source.put("lrts_session","");
  source.put("lrts_q","0");
  try{
    var map=new Packages.java.util.HashMap();
    LR_LOGIN_FIELDS.forEach(function(field){map.put(field.name,"");});
    java.upLoginData(map);
  }catch(clearError){}
  java.longToast("个人抓包会话已清除；使用前请重新抓包填写");
  try{java.reLoginView();}catch(refreshError){}
}

