@js:

var raw=String(src||"");
var body;
if(String(baseUrl||"").indexOf("data:;base64,")===0){
  var marker=JSON.parse(String(java.hexDecodeToString(raw)||"{}"));
  if(marker.kind!=="lrtsBookAudio")throw new Error("未知的懒人听书章节标记");
  var now=String(Date.now());
  var playUrl=lrtsAppUrl(java,source,"/yyting/v3/gateway/getListenPath",{
    costInfo:now+"-"+now+"-0",
    effect:"0",
    entityId:String(marker.bookId||""),
    entityType:String(marker.entityType||"1"),
    opType:"0",
    quality:"1",
    resId:String(marker.resId||""),
    section:String(marker.section||""),
    trackId:String(marker.trackId||""),
    vid:""
  });
  body=JSON.parse(String(java.ajax(playUrl)||"{}"));
}else{
  body=JSON.parse(raw);
}
var model=body.data&&body.data.length!==undefined?body.data[0]:body.data;
model=model||{};
var path=String(model.path||model.url||"");
var eKey=String(model.key||"");
var encrypted=!!eKey||/.mgg(?:$|[?#])/i.test(path);
if(encrypted){
  if(!path)throw new Error("加密歌曲没有返回媒体地址");
  if(!eKey)throw new Error("加密歌曲没有返回 eKey，无法解密");
  var cachePath="";
  try{
    cachePath=String(java.downloadFile(path+", "+JSON.stringify({type:"mgg"}))||"");
    if(!cachePath)throw new Error("加密歌曲下载失败");
    var audioBytes=java.readFile(cachePath);
    if(!audioBytes||!audioBytes.length)throw new Error("加密歌曲缓存为空");
    lrtsQmcDecrypt(java,audioBytes,eKey);
    var format=lrtsAudioFormat(audioBytes);
    path=lrtsAudioDataSource(audioBytes,format);
  }finally{
    if(cachePath)try{java.deleteFile(cachePath);}catch(deleteError){}
  }
}
if(!path)throw new Error(String(body.msg||"App 播放地址获取失败，请确认账号权益或更新 HAR 会话"));
path;

