if (fl) {
a=org.jsoup.Jsoup.parse(fl).select(".mav_3 a");
push("分类",null,1)
push("最近","https://www.xxwx8.com/",0.25)
    for(var i=0;i<a.length;i++){
        title=a[i].text()
        url=a[i].attr("href")
        size=0.25;
        url=url
        url=String(url).replace(/.html/,"_{{page}}.html").replace(/xxchannel/,"xxlist")
        push(title,url,size)
    };


